private let COUNTRY_BY_CODE: [String: CountryInfo] = Dictionary(uniqueKeysWithValues: COUNTRIES.map { ($0.code, $0) })

func currencyForCountry(_ code: String) -> String {
    COUNTRY_BY_CODE[code]?.currency ?? "USD"
}

func isKnownCountry(_ code: String) -> Bool {
    COUNTRY_BY_CODE[code] != nil
}

/// i18n key for a continent group's label in a country picker, e.g.
/// "deposer.region_europe" — shared by the country picker so the mapping
/// lives in exactly one place.
func regionLabelKey(_ region: ContinentRegion) -> String {
    "deposer.region_" + region.rawValue.lowercased()
}

/// One continent group's countries, for a picker's Section list — a plain
/// struct rather than a tuple so SwiftUI's `ForEach(id:)` has an unambiguous
/// `Hashable` keypath to use (no local compiler here to double-check a tuple
/// keypath actually resolves the way it's expected to).
struct CountryRegionGroup: Hashable {
    let region: ContinentRegion
    let codes: [String]
}

/// Groups the full country list into continents for pickers — Morocco
/// pinned first as the platform's home market, then continents in a fixed,
/// stable order (mirrors web's COUNTRY_REGIONS / Android's COUNTRY_REGIONS).
let COUNTRY_REGIONS: [CountryRegionGroup] = {
    let order: [ContinentRegion] = [.morocco, .africa, .europe, .asia, .northAmerica, .southAmerica, .oceania]
    return order.map { region in CountryRegionGroup(region: region, codes: COUNTRIES.filter { $0.region == region }.map { $0.code }) }
}()

